#!/usr/bin/env python3
"""
Builder for mmpR5 pipeline v3 — modular Google Colab notebooks.

Run:  python3 build_notebooks.py
Output: mmpR5_pipeline_v3/*.ipynb  (7 notebooks)

Bug fixes applied to embedded cell data:
  [1] m2 cell 4: _REF_SEQ_NAME auto-detected from FASTA _rec.id, so region
      specifiers work regardless of FASTA header (e.g. H37Rv_NC000962_MTBKO_20180411
      vs NC_000962.3).
  [2] controller: module names corrected to actual .ipynb filenames:
      m1_data_acquisition, m2_assembly_and_extraction, m3_structural_features.
"""
import json, uuid
from pathlib import Path

OUT_DIR = Path(__file__).parent
OUT_DIR.mkdir(parents=True, exist_ok=True)

def _id(): return uuid.uuid4().hex[:8]

def _src(text):
    lines = text.split("\n")
    while lines and not lines[-1].strip(): lines.pop()
    return ([l + "\n" for l in lines[:-1]] + [lines[-1]]) if lines else [""]

def _cell(c):
    if c["type"] == "markdown":
        return {"cell_type":"markdown","id":_id(),"metadata":{},"source":_src(c["src"])}
    m = {"tags": c["tags"]} if c.get("tags") else {}
    return {"cell_type":"code","execution_count":None,"id":_id(),
            "metadata":m,"outputs":[],"source":_src(c["src"])}

def write_nb(name, cell_data):
    cells = [_cell(c) for c in cell_data]
    nb = {"cells": cells,
          "metadata": {"kernelspec": {"display_name":"Python 3",
                                      "language":"python","name":"python3"}},
          "nbformat": 4, "nbformat_minor": 5}
    p = OUT_DIR / name
    p.write_text(json.dumps(nb, indent=1))
    print(f"  Written: {name}  ({p.stat().st_size:>8,} bytes)")

